"""Edições de texto do curso Perplexity - Essentials (fase A).

Formato: (licao, bloco, caminho_a_partir_do_bloco, texto_novo). bloco=None = a própria lição.
Fonte: Pesquisa Conteudo Onda 1/Ementa Completa/perplexity-essentials/roteiros/roteiro-articulate-essentials.md
"""

E = []


def add(licao, bloco, caminho, texto):
    E.append((licao, bloco, caminho, texto))


def head(l, b, t):
    add(l, b, "items[0].heading", t)


def par(l, b, t):
    add(l, b, "items[0].paragraph", t)


def tit(l, b, i, t):
    add(l, b, f"items[{i}].title", t)


def desc(l, b, i, t):
    add(l, b, f"items[{i}].description", t)


def back(l, b, i, t):
    add(l, b, f"items[{i}].back.description", t)


def front(l, b, i, t):
    add(l, b, f"items[{i}].front.description", t)


def kc_q(l, b, t):
    add(l, b, "items[0].title", t)


def kc_fb(l, b, i, t):
    add(l, b, f"items[0].answers[{i}].feedback", t)


def lista(l, b, i, t):
    add(l, b, f"items[{i}].paragraph", t)


OBJ = '<p>Ao final desta lição, você será capaz de:</p>'
CLIQUE_CARTAO = '<p>Clique em cada cartão para ver o verso.</p>'

