L = 8


def q(b, caminho, t):
    add(L, b, caminho, t)


add(L, None, 'description', 'Teste o que você aprendeu: como funciona um motor de respostas, o que pode entrar na pergunta, como escolher a profundidade da busca, como conferir citações e fontes e como organizar a pesquisa e produzir uma síntese citada com limites declarados.')
q(0, 'title', 'Uma síntese citada auditada termina com uma __________ para declarar o que não foi possível confirmar.')
q(1, 'answers[0].title', 'Falso')
q(1, 'answers[0].feedback', 'Não. A afirmação é verdadeira: PDFs digitalizados como imagem podem não ser lidos, por isso o curso recomenda arquivos com texto selecionável.')
q(1, 'answers[1].title', 'Verdadeiro')
q(1, 'answers[1].feedback', 'Correto. PDFs digitalizados como imagem podem não ser lidos pela ferramenta; arquivos com texto selecionável evitam o problema.')
q(2, 'title', 'Relacione cada tipo de fonte ao papel que ela tem numa pesquisa com conferência rigorosa de citações.')
q(3, 'answers[0].feedback', 'Correto. A Pesquisa Pro encadeia várias buscas e combina dezenas de fontes, o que serve a perguntas ambíguas e comparações, e preserva a Research mensal.')
q(3, 'answers[1].feedback', 'Não. A Research produz relatório longo e tem cota de 1 por mês no plano gratuito — justamente a cota que a situação pede para preservar.')
q(3, 'answers[2].feedback', 'Não. A busca padrão costuma se apoiar em poucas fontes; serve a fatos simples e primeiras aproximações, não a uma comparação entre várias fontes.')
q(3, 'answers[3].title', 'Iniciar uma nova pesquisa')
q(3, 'answers[3].feedback', 'Não. Iniciar uma nova pesquisa controla o contexto do Thread, mas não define a profundidade da busca.')
q(4, 'answers[0].feedback', 'Não. Um texto bem escrito não mostra de onde veio a informação.')
q(4, 'answers[1].feedback', 'Não. Tópicos facilitam a leitura, mas não ligam a frase à fonte.')
q(4, 'answers[2].title', 'Os números de citação vinculados às afirmações da resposta')
q(4, 'answers[2].feedback', 'Correto. Os números de citação levam à página de origem, onde você confere se o trecho sustenta a frase. Eles mostram onde conferir; não garantem que a frase esteja certa.')
q(4, 'answers[3].feedback', 'Não. Um resumo sem referências não deixa trilha para conferir.')
q(5, 'title', 'Associe cada rótulo da interface em português ao equivalente em inglês e à sua função.')
q(6, 'answers[0].title', 'Falso')
q(6, 'answers[0].feedback', 'Correto. A citação é uma trilha de auditoria, não um selo de verdade: mesmo com citação, pode haver erro de atribuição (37% dos casos no teste do Tow Center).')
q(6, 'answers[1].title', 'Verdadeiro')
q(6, 'answers[1].feedback', 'Não. A citação mostra onde conferir, mas não garante que a fonte diga o que a frase afirma. A conferência no original continua necessária.')
q(7, 'answers[0].feedback', 'Não. Pergunta genérica produz resposta genérica, e o tempo de resposta não mede qualidade.')
q(7, 'answers[1].feedback', 'Não. Reaproveitar o Thread de outro assunto contamina a resposta com premissas antigas, e a Pesquisa Pro se escolhe pelo tipo de pergunta, não por haver cota.')
q(7, 'answers[2].feedback', 'Correto. Pergunta delimitada, busca padrão para a primeira aproximação e Pesquisa Pro quando a pergunta tiver várias facetas: profundidade proporcional ao problema.')
q(7, 'answers[3].feedback', 'Não. Uma pergunta ampla sobre vários assuntos tira o controle da pesquisa, e a Research (1 por mês no plano gratuito) não é ponto de partida.')
q(8, 'answers[0].feedback', 'Não. A busca depende de uma pergunta delimitada: formular vem antes de buscar.')
q(8, 'answers[1].feedback', 'Não. Proteger vem primeiro: o semáforo decide o que pode entrar na pergunta antes de você escrevê-la.')
q(8, 'answers[2].feedback', 'Correto. Proteger, formular, buscar, conferir e sintetizar — e, se a conferência revelar uma lacuna, volta-se a formular.')
q(8, 'answers[3].feedback', 'Não. Só se confere depois de buscar, quando já há citações para abrir.')
q(9, 'answers[0].feedback', 'Não. A pergunta é sobre o uso da ferramenta, não sobre o tema da pesquisa.')
q(9, 'answers[1].feedback', 'Correto. A pergunta delimita tema, tipo de fonte (revisados por pares), período (últimos cinco anos) e contexto (educação superior).')
q(9, 'answers[2].feedback', 'Não. “Sempre positivos” embute uma conclusão na pergunta e enviesa a busca.')
q(9, 'answers[3].feedback', 'Não. A pergunta é ampla e subjetiva: sem recorte, sem fontes aceitas e sem formato.')
q(10, 'answers[0].feedback', 'Não. O histórico (Recentes) ajuda a reencontrar pesquisas, mas não aplica instrução persistente.')
q(10, 'answers[1].feedback', 'Não. “Sua Biblioteca” é o nome do histórico no app Android: guarda pesquisas avulsas e não substitui um Projeto.')
q(10, 'answers[2].feedback', 'Correto. O Projeto reúne conversas, arquivos e uma instrução aplicada a todas as pesquisas feitas dentro dele.')
q(10, 'answers[3].feedback', 'Não. Recentes guarda pesquisas avulsas, sem organização por tema nem instrução fixa.')
q(12, 'answers[0].feedback', 'Não. As cotas estão trocadas: são 3 Pesquisas Pro por dia e 1 Research por mês.')
q(12, 'answers[1].feedback', 'Não. A periodicidade está errada: a Pesquisa Pro é contada por dia, e a Research, por mês.')
q(12, 'answers[2].feedback', 'Não. A busca básica é praticamente ilimitada, e as cotas de Pesquisa Pro e Research estão com a periodicidade invertida.')
q(12, 'answers[3].feedback', 'Correto. Segundo a ajuda oficial (02/09/2026): busca básica praticamente ilimitada, 3 Pesquisas Pro por dia e 1 Research por mês.')
q(13, 'answers[0].feedback', 'Não. O NotebookLM serve para estudar um conjunto fechado de documentos já reunidos; não é a fonte oficial da norma.')
q(13, 'answers[1].feedback', 'Não. A Perplexity dá a pista; a norma se cita a partir do repositório oficial.')
q(13, 'answers[2].feedback', 'Correto. O repositório oficial é o único lugar de onde se cita uma norma ou decisão, depois da pista dada pela IA.')
q(13, 'answers[3].feedback', 'Não. O buscador tem cobertura ampla, mas não é a fonte oficial: no máximo, leva até ela.')
q(14, 'answers[0].feedback', 'Não. O erro está na descrição da Perplexity: ela liga as afirmações às fontes por citações.')
q(14, 'answers[1].feedback', 'Não. As funções estão trocadas entre as três ferramentas.')
q(14, 'answers[2].feedback', 'Não. A Perplexity não se limita a listar páginas, e o chatbot sem busca não cita fontes.')
q(14, 'answers[3].feedback', 'Correto. O buscador lista páginas, o chatbot sem busca responde a partir do treinamento e o motor de respostas sintetiza páginas recuperadas, com citações.')
q(15, 'answers[0].feedback', 'Não. Os controles não ficam na tela de anexos: Retenção de Dados de IA e Memória estão em Configurações, e a navegação anônima é um botão da interface.')
q(15, 'answers[1].feedback', 'Não. A navegação anônima não é anonimato total, e a Retenção de Dados de IA é documentada nos planos pagos — no gratuito, é preciso conferir se aparece.')
q(15, 'answers[2].feedback', 'Não. Desativar a Memória não impede o envio da pergunta, e a navegação anônima não salva a atividade entre sessões.')
q(15, 'answers[3].feedback', 'Correto. Retenção de Dados de IA e Memória ficam em Configurações; a navegação anônima é um botão da interface e não substitui a minimização.')
q(16, 'answers[0].feedback', 'Não. A navegação anônima não salva o histórico, mas o caso completo continua sendo enviado aos servidores.')
q(16, 'answers[1].feedback', 'Não. Mesmo em conta institucional, envia-se só o trecho necessário, minimizado.')
q(16, 'answers[2].feedback', 'Não. Manter os dados do cliente contraria a minimização; dado de pessoa identificável é vermelho no semáforo.')
q(16, 'answers[3].feedback', 'Correto. Trocar nomes e identificadores por rótulos genéricos e enviar só o trecho necessário é a minimização.')
q(17, 'answers[0].title', 'Falso')
q(17, 'answers[0].feedback', 'Não. A afirmação é verdadeira: as instruções do curso se referem à versão web, e os aplicativos servem de complemento.')
q(17, 'answers[1].title', 'Verdadeiro')
q(17, 'answers[1].feedback', 'Correto. O curso usa a versão web, em perplexity.ai, cujos rótulos foram observados na produção; os aplicativos são complemento.')
q(18, 'title', 'Ao validar uma citação, também é preciso verificar se país, período e população coincidem com a afirmação. Esse critério corresponde ao __________.')
q(19, 'answers[0].feedback', 'Correto. Abrir a citação, localizar o trecho e conferir se ele sustenta a frase no contexto é a conferência que o curso ensina.')
q(19, 'answers[1].feedback', 'Não. Outra IA pode repetir o mesmo erro; comparar respostas não substitui a fonte original.')
q(19, 'answers[2].feedback', 'Não. Página de resumo é fonte secundária: dá contexto, mas não comprova uma afirmação importante.')
q(19, 'answers[3].feedback', 'Não. Um nome conhecido não prova que a fonte diz o que a frase afirma; é preciso ler o trecho.')

